import urllib.request, struct, zlib, collections
logos = {
 "golden-state-valkyries":"https://img.thesports.com/basketball/team/380d81d4050b81debf9a5500239e96d0.png",
 "las-vegas-aces":"https://img.thesports.com/basketball/team/ce8ab1125fdb3fdbd8c09dba8c437c49.png",
 "dallas-wings":"https://img.thesports.com/basketball/team/58709b9e7964e03c28ebe777ef823eca.png",
 "bluefire":"https://img.thesports.com/basketball/team/307e4a3f21d713ddea9eef1dc8b26f3d.png",
}
for n,u in logos.items():
    req = urllib.request.Request(u, headers={"User-Agent":"Mozilla/5.0"})
    try:
        d = urllib.request.urlopen(req, timeout=15).read()
    except Exception as e:
        print(n, "ERR", e); continue
    sig = d[:8] == b"\x89PNG\r\n\x1a\n"
    w,h,bd,ct,cm,fm,il = struct.unpack(">IIBBBBB", d[16:29])
    chunks=[]; i=8
    while i < len(d):
        ln,=struct.unpack(">I", d[i:i+4]); chunks.append(d[i+4:i+8].decode()); i += 12+ln
    print(n, len(d), "bytes png" if sig else "NOT PNG", f"{w}x{h} depth={bd} colortype={ct} interlace={il}", sorted(set(chunks)))
